item.content:encoded:
.site-description {
    display: block;
}

.cover-img-430 {
    height: 430px;
}

.pad-right-10 {
    padding-right: 10%;
}

.pad-left-10 {
    padding-left: 10%;
}

.libcal {
    height: 600px !important;
}

.alignfull-bg {
    background-color:#9ab7c166;
    padding-top: 50px;
    margin-top: -100px;
}
.category-workshops figure.featured-media {
    display: none;
} 

.margin-top-none {
    margin-top: 0px !important;
}

.margin-bottom-none {
    margin-bottom: 0px !important;
}

.margin-top-half {
    margin-top: 4rem !important;
}

/* overriding opened-cloner css */

body svg {
	width: initial;
	height: initial;
}

fix bottom footer block padding 
.site-bottom-footer-inner-wrap {
    padding-top: 0px;
    padding-bottom: 0px;
}

/*
.ns-cloner-rt-item{
	width: 100% !important;
	box-shadow: none !important;
	border: 1px solid #ccc;
	margin-left: 0px !important
}
*/


/* Sign up page clean up */

.ns-cloner-rt-item h6{
	font-weight: 600;
	text-transform: capitalize;
	font-size: 16px !important;
	border-bottom: 1px solid #ccc !important;
}


.ns-cloner-rt-items{
	display: grid;
	margin-bottom: 50px
}

.ns-cloner-rt-item{
	float: none;
	width: 100% !important;
		margin: 0 0 0 !important;
		display:flex;
	flex-direction: column;
	justify-content: start;
	box-shadow: none !important;
	border: 1px solid #ccc;
}

.ns-cloner-rt-item label{
	padding: 20px;
	background: none !important;
	flex-grow: 1
}

#ns-cloner-rt .ns-cloner-rt-item [type="radio"]:checked + label{
	background: var(--global-palette1) !important;
}

@media (min-width: 780px){
.ns-cloner-rt-items{
		grid-template-columns: 1fr 1fr 1fr;
		grid-gap: 30px;
	}
}


@media (max-width: 780px){
 .ns-cloner-rt-items{
		grid-template-columns: 1fr ;
		grid-gap: 35px;
	}
}

@media (max-width: 1300px){
.page-id-241 #custom_signup_docs{
	max-width: 100%;
}

	#custom_signup_wrapper{
		flex-direction: column!important
	}
}

/* changing layout for sign up page further */
.mu_register.wp-signup-container ul:first-of-type{
	max-height: 150px;
	overflow: auto;
	margin-bottom: 30px;
	padding-block: 10px;
	padding-inline: 30px;
	margin-left: 0;
	border: 1px solid #ccc;
}

#custom_signup_wrapper{
	flex-direction: column;
}

@media (min-width: 1300px) {
  .page-id-241 #custom_signup_docs {
    max-width: 100%;
  }
}

.mu_register.wp-signup-container label{
	margin-top: 40px
}

.mu_register.wp-signup-container legend {
	color: #1d1d1d;
	background: none;
}

.mu_register.wp-signup-container  .wp-signup-radio-buttons{
	margin-bottom: 2px
}

.mu_register .privacy-intro .wp-signup-radio-button{display: block}

.mu_register.wp-signup-container  .checkbox input{
 margin-right: 5px;
 margin-bottom: 10px
}

.mu_register.wp-signup-container input[type="text"], select{
	padding: 10px;
	font-size: 1.2rem !important;
}

#custom_signup_docs p, #custom_signup_docs h4, #custom_signup_docs li{
	margin-bottom: 6px
}

#custom_signup_docs h4{
	margin-top: 20px;
}

#custom_signup_docs{
	margin-inline: 30px;
	background: rgb(0, 0, 0, .05);
	border: 1px solid #ccc;
	padding: 30px
}
